if(typeof require==='function'){var Classy=require('./classy');var PlayerState=require('./playerstate');}var Player=Classy.newClass();Player.fields({id:null,queued:false,enqueueTime:null,team:0});Player.constructor(function(id,queued,enqueueTime,team){this.id=id;this.queued=queued;this.enqueueTime=enqueueTime;this.team=team;});Player.methods({setPlayerState:function(playerState){this.id=playerState.getPlayerId();this.queued=playerState.getQueued();this.enqueueTime=playerState.getEnqueueTime();this.team=playerState.getTeam();},getPlayerState:function(){var ps=PlayerState.withState(this.id,this.queued,this.enqueueTime,this.team);return ps;},getId:function(){return this.id;},getEnqueueTime:function(){return this.enqueueTime;},getTeam:function(){return this.team;},setTeam:function(team){this.team=team;}});if(typeof module==='object'){module.exports=Player;}